def fmt(x,n=6):return '—' if x is None else f'{x:.{n}g}'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def eptext(e):
 if not e:return 'No reliable independent ephemeris.'
 return f"P={e['P']:.10f} ± {e['P_error']:.3g} d; Tref={e['Tref']:.7f} ± {e['Tref_error']:.3g} BTJD, reference cycle {e['reference_cycle']}; χ²/dof={e['chi2']:.2f}/{e['dof']}, O−C RMS={e['oc_rms_minutes']:.3f} min. Errors include grid/red-noise and ephemeris scatter scaling, conditional on shape/baseline."
