 phase=s['profile_phase'];off=[x for x in r['census'] if min(abs((x['phase']+.5)%1-.5),abs((x['phase']-phase+.5)%1-.5))>max(.03,r['shape']['T14']/r['ephemeris']['P'])]
 bgmin=min(e['depth_with_background']/e['depth'] for e in ev if e['depth_with_background'] is not None)
